arguments.command:
cat > /app/solve.py <<'EOF'
import inspect
import numpy as np
import mteb

MODEL = "BAAI/bge-small-zh-v1.5"
REV = "7999e1d3359715c523056ef9478215996d62a620"
QUERY = "terminal-bench"

with open("/app/data.txt", encoding="utf-8") as f:
    docs = [l.rstrip("\n") for l in f if l.strip()]

model = mteb.get_model(MODEL, revision=REV)

def encode(texts):
    kwargs = {}
    try:
        params = inspect.signature(model.encode).parameters
    except (TypeError, ValueError):
        params = {}
    if "task_name" in params:
        kwargs["task_name"] = "STS22"
    try:
        return np.asarray(model.encode(texts, **kwargs))
    except TypeError:
        return np.asarray(model.encode(texts))

E = encode([QUERY] + docs)
E = E / np.linalg.norm(E, axis=1, keepdims=True)
sims = E[1:] @ E[0]
order = np.argsort(-sims)
for r, i in enumerate(order[:8], 1):
    print(r, round(float(sims[i]), 4), docs[i][:70])
res = docs[order[4]]
with open("/app/result.txt", "w", encoding="utf-8") as f:
    f.write(res + "\n")
print("RESULT:", res)
EOF
cd /app && python3 solve.py 2>&1 | tail -12

